import React from 'react';

import { ValueBottomAxis } from '../../../core/components/axes/components/ValueBottomAxis.js';
import { ChartGrid } from '../../../core/components/chart-grid/ChartGridRoot.js';
import { AREAS } from '../../constants/xy-chart-grid-areas.js';
import { useAxesTicks } from '../../hooks/useAxesTicks.js';
import { useVisibleAxes } from '../../hooks/useVisibleAxes.js';

export function XYChartBottomAxisArea() {
  const { bottomTicks } = useAxesTicks();
  const { config, scales } = useVisibleAxes();
  const bottomConfig = config.bottom;
  const bottomScale = scales.bottom;

  return bottomConfig === undefined || bottomScale === undefined ? null : (
    <ChartGrid.GridArea gridArea={AREAS.bottomAxis}>
      {({ availableWidth, availableHeight }) => (
        <ValueBottomAxis
          ticks={bottomTicks.ticks}
          formattedTicks={bottomTicks.formattedTicks}
          scale={bottomScale}
          containerHeight={availableHeight}
          containerWidth={availableWidth}
          label={bottomConfig.label}
        />
      )}
    </ChartGrid.GridArea>
  );
}

XYChartBottomAxisArea['displayName'] = 'XYChartValueBottomAxisArea';
